function adapt(input, solve, kit) {
  const [urls, edges, startUrl] = input;
  const links = new Map(urls.map((url) => [url, []]));
  for (const [from, to] of edges) links.get(urls[from]).push(urls[to]);
  const hostname = (url) => url.split('/')[2];
  const fetched = new Set(), start = Date.now();
  let failure = null;
  const htmlParser = {
    getUrls(url) {
      if (!links.has(url)) failure = failure ?? `getUrls was called with ${JSON.stringify(url)}, which is not a known url.`;
      else if (hostname(url) !== hostname(startUrl)) failure = failure ?? `getUrls was called for ${url}, which is on another hostname.`;
      else if (fetched.has(url)) failure = failure ?? `${url} was fetched twice.`;
      fetched.add(url);
      kit.trace(`getUrls("${url}") starts`);
      const found = [...(links.get(url) || [])];
      return new Promise((resolve) => setTimeout(() => {
        kit.trace(`getUrls("${url}") returns ${found.length} link${found.length === 1 ? '' : 's'}`);
        resolve(found);
      }, 15));
    },
  };
  return Promise.resolve(solve(startUrl, htmlParser)).then((result) => {
    if (failure) throw new Error(failure);
    if (!Array.isArray(result)) throw new Error('crawl must resolve with an array of urls.');
    kit.trace(`crawl resolves with ${result.length} url${result.length === 1 ? '' : 's'}`);
    return { urls: [...result].sort(), time: Date.now() - start };
  });
}

