async function crawl(startUrl, htmlParser) {
  const hostname = (url) => url.split('/')[2];
  const host = hostname(startUrl);
  const seen = new Set([startUrl]);
  const visit = async (url) => {
    const links = await htmlParser.getUrls(url);
    const fetches = [];
    for (const link of links) {
      if (seen.has(link) || hostname(link) !== host) continue;
      seen.add(link);
      fetches.push(visit(link));
    }
    await Promise.all(fetches);
  };
  await visit(startUrl);
  return [...seen];
}

