async function crawl(startUrl, htmlParser) {
  const hostOf = (url) => /^http:\/\/([^/]*)/.exec(url)[1];
  const found = [startUrl];
  let frontier = [startUrl];
  // Breadth-first, one level at a time: every page of a level is fetched in parallel.
  while (frontier.length > 0) {
    const lists = await Promise.all(frontier.map((url) => htmlParser.getUrls(url)));
    frontier = [];
    for (const link of lists.flat()) {
      if (hostOf(link) !== hostOf(startUrl) || found.includes(link)) continue;
      found.push(link);
      frontier.push(link);
    }
  }
  return found;
}

