function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const small = size === 'small';
  const pool = ['news.yahoo.com', 'yahoo.com', 'news.google.com', 'example.org', 'a.example.org', 'example.org.uk', 'leet-code.com', 'x1.y2.z3'];
  const hosts = [];
  const hostCount = small ? 1 + pick(3) : 2 + pick(4);
  while (hosts.length < hostCount) {
    const host = pool[pick(pool.length)];
    if (!hosts.includes(host)) hosts.push(host);
  }
  const words = ['news', 'us', 'topics', 'a', 'b', 'c', '1', '2', 'example.org'];
  const count = small ? 1 + pick(8) : 600 + pick(401);
  const urls = [], seen = new Set(), home = [];
  for (let attempt = 0; urls.length < count && attempt < 50 * count; attempt++) {
    // Most pages are on the first hostname, so the crawl has work to do.
    const host = rand() < 0.65 ? hosts[0] : hosts[pick(hosts.length)];
    let path = '';
    if (small) {
      const depth = pick(4);
      for (let d = 0; d < depth; d++) path += `/${words[pick(words.length)]}`;
      if (depth > 0 && rand() < 0.3) path += '/';
    } else path = `/${words[pick(words.length)]}/${urls.length}`;
    const url = `http://${host}${path}`;
    if (!seen.has(url)) {
      seen.add(url);
      if (host === hosts[0]) home.push(urls.length);
      urls.push(url);
    }
  }
  const edges = [];
  const edgeCount = small ? pick(2 * urls.length + 1) : Math.min(2000, 2 * urls.length);
  // A chain through the first hostname's pages makes long paths likely; the other links are random.
  for (let k = 0; k + 1 < home.length && edges.length < edgeCount; k++) if (rand() < 0.7) edges.push([home[k], home[k + 1]]);
  while (edges.length < edgeCount) edges.push([pick(urls.length), pick(urls.length)]);
  const start = home.length > 0 && rand() < 0.8 ? home[pick(Math.min(home.length, small ? home.length : 10))] : pick(urls.length);
  return [urls, edges, urls[start]];
}
